using UnityEngine;

namespace SaintVessel
{
    /// <summary>Builds the whole app from code, so the project needs only an empty scene (generated by BuildScript).</summary>
    public static class AppBootstrap
    {
        static bool _booted;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        static void Boot()
        {
            if (_booted) return;
            _booted = true;

            Application.targetFrameRate = 60;
            QualitySettings.vSyncCount = 0;
            Screen.sleepTimeout = SleepTimeout.NeverSleep;
            Resources.Load<ShaderVariantAnchor>("ShaderVariantAnchor");   // touch: keeps MToon variants alive

            var go = new GameObject("SaintVessel");
            Object.DontDestroyOnLoad(go);

            var settings = AppSettings.Load();
            var env = go.AddComponent<EnvironmentController>();
            env.Init(settings);
            var tracking = go.AddComponent<TrackingService>();
            var avatar = go.AddComponent<AvatarController>();
            avatar.Init(settings, tracking, env);
            var ui = go.AddComponent<SettingsUI>();
            ui.Init(settings, tracking, avatar, env);
            tracking.Init(settings);
        }
    }
}
